using System;using System.IO;using System.Reflection;using System.Collections;using System.Collections.Generic;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class DamageNumberCheck{
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var w=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",flags).GetValue(g);w.Reset(g.Run);var labels=(IList)typeof(InkBattleWorld).GetField("damageLabels",flags).GetValue(w);double expected=0;for(int tick=0;tick<90;tick++){var enemies=new List<EnemyState>(g.Run.Enemies);var hp=new List<double>();foreach(var e in enemies)hp.Add(e.Hp);w.BeforeTick(g.Run);g.Run.Tick();w.AfterTick(g.Run,true);for(int i=0;i<enemies.Count;i++)expected+=Math.Max(0,Math.Min(hp[i],hp[i]-enemies[i].Hp));if(expected>0)break;}g.PresentBattle();double observed=0;int active=0;foreach(var label in labels){var t=label.GetType();if((float)t.GetField("age").GetValue(label)>=.65f)continue;observed+=(double)t.GetField("damage").GetValue(label);active++;}if(active==0||Math.Abs(expected-observed)>1e-6||labels.Count>24)throw new Exception("Damage total mismatch");var result=new{passed=true,expected,observed,active,allocated=labels.Count};File.WriteAllText(Path.GetFullPath("../docs/evidence/damage-number-check.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/damage-numbers.png"));return result;}}
